func testClusterColorControlCommandFailClosed() {
    let controller = MTRDeviceController()
    let device = MTRDevice(nodeID: n(1), controller: controller)
    let baseDevice: MTRBaseDevice = device
    _ = (device, baseDevice)
    guard let cluster = MTRClusterColorControl(device: device, endpointID: n(1), queue: DispatchQueue.global()) else {
        mtrRequire(false, "MTRClusterColorControl init")
        return
    }
    cluster.colorLoopSet(with: MTRColorControlClusterColorLoopSetParams(), expectedValues: [], expectedValueInterval: n(1), completion: { err in mtrExpectInvalidState(err) })
    cluster.colorLoopSet(with: MTRColorControlClusterColorLoopSetParams(), expectedValues: [], expectedValueInterval: n(1), completionHandler: { err in mtrExpectInvalidState(err) })
    cluster.enhancedMoveHue(with: MTRColorControlClusterEnhancedMoveHueParams(), expectedValues: [], expectedValueInterval: n(1), completion: { err in mtrExpectInvalidState(err) })
    cluster.enhancedMoveHue(with: MTRColorControlClusterEnhancedMoveHueParams(), expectedValues: [], expectedValueInterval: n(1), completionHandler: { err in mtrExpectInvalidState(err) })
    cluster.enhancedMoveToHueAndSaturation(with: MTRColorControlClusterEnhancedMoveToHueAndSaturationParams(), expectedValues: [], expectedValueInterval: n(1), completion: { err in mtrExpectInvalidState(err) })
    cluster.enhancedMoveToHueAndSaturation(with: MTRColorControlClusterEnhancedMoveToHueAndSaturationParams(), expectedValues: [], expectedValueInterval: n(1), completionHandler: { err in mtrExpectInvalidState(err) })
    cluster.enhancedMoveToHue(with: MTRColorControlClusterEnhancedMoveToHueParams(), expectedValues: [], expectedValueInterval: n(1), completion: { err in mtrExpectInvalidState(err) })
    cluster.enhancedMoveToHue(with: MTRColorControlClusterEnhancedMoveToHueParams(), expectedValues: [], expectedValueInterval: n(1), completionHandler: { err in mtrExpectInvalidState(err) })
    cluster.enhancedStepHue(with: MTRColorControlClusterEnhancedStepHueParams(), expectedValues: [], expectedValueInterval: n(1), completion: { err in mtrExpectInvalidState(err) })
    cluster.enhancedStepHue(with: MTRColorControlClusterEnhancedStepHueParams(), expectedValues: [], expectedValueInterval: n(1), completionHandler: { err in mtrExpectInvalidState(err) })
    cluster.moveColorTemperature(with: MTRColorControlClusterMoveColorTemperatureParams(), expectedValues: [], expectedValueInterval: n(1), completion: { err in mtrExpectInvalidState(err) })
    cluster.moveColorTemperature(with: MTRColorControlClusterMoveColorTemperatureParams(), expectedValues: [], expectedValueInterval: n(1), completionHandler: { err in mtrExpectInvalidState(err) })
    cluster.moveColor(with: MTRColorControlClusterMoveColorParams(), expectedValues: [], expectedValueInterval: n(1), completion: { err in mtrExpectInvalidState(err) })
    cluster.moveColor(with: MTRColorControlClusterMoveColorParams(), expectedValues: [], expectedValueInterval: n(1), completionHandler: { err in mtrExpectInvalidState(err) })
    cluster.moveHue(with: MTRColorControlClusterMoveHueParams(), expectedValues: [], expectedValueInterval: n(1), completion: { err in mtrExpectInvalidState(err) })
    cluster.moveHue(with: MTRColorControlClusterMoveHueParams(), expectedValues: [], expectedValueInterval: n(1), completionHandler: { err in mtrExpectInvalidState(err) })
    cluster.moveSaturation(with: MTRColorControlClusterMoveSaturationParams(), expectedValues: [], expectedValueInterval: n(1), completion: { err in mtrExpectInvalidState(err) })
    cluster.moveSaturation(with: MTRColorControlClusterMoveSaturationParams(), expectedValues: [], expectedValueInterval: n(1), completionHandler: { err in mtrExpectInvalidState(err) })
    cluster.moveToColorTemperature(with: MTRColorControlClusterMoveToColorTemperatureParams(), expectedValues: [], expectedValueInterval: n(1), completion: { err in mtrExpectInvalidState(err) })
    cluster.moveToColorTemperature(with: MTRColorControlClusterMoveToColorTemperatureParams(), expectedValues: [], expectedValueInterval: n(1), completionHandler: { err in mtrExpectInvalidState(err) })
    cluster.moveToColor(with: MTRColorControlClusterMoveToColorParams(), expectedValues: [], expectedValueInterval: n(1), completion: { err in mtrExpectInvalidState(err) })
    cluster.moveToColor(with: MTRColorControlClusterMoveToColorParams(), expectedValues: [], expectedValueInterval: n(1), completionHandler: { err in mtrExpectInvalidState(err) })
    cluster.moveToHueAndSaturation(with: MTRColorControlClusterMoveToHueAndSaturationParams(), expectedValues: [], expectedValueInterval: n(1), completion: { err in mtrExpectInvalidState(err) })
    cluster.moveToHueAndSaturation(with: MTRColorControlClusterMoveToHueAndSaturationParams(), expectedValues: [], expectedValueInterval: n(1), completionHandler: { err in mtrExpectInvalidState(err) })
    cluster.moveToHue(with: MTRColorControlClusterMoveToHueParams(), expectedValues: [], expectedValueInterval: n(1), completion: { err in mtrExpectInvalidState(err) })
    cluster.moveToHue(with: MTRColorControlClusterMoveToHueParams(), expectedValues: [], expectedValueInterval: n(1), completionHandler: { err in mtrExpectInvalidState(err) })
    cluster.moveToSaturation(with: MTRColorControlClusterMoveToSaturationParams(), expectedValues: [], expectedValueInterval: n(1), completion: { err in mtrExpectInvalidState(err) })
    cluster.moveToSaturation(with: MTRColorControlClusterMoveToSaturationParams(), expectedValues: [], expectedValueInterval: n(1), completionHandler: { err in mtrExpectInvalidState(err) })
    cluster.stepColorTemperature(with: MTRColorControlClusterStepColorTemperatureParams(), expectedValues: [], expectedValueInterval: n(1), completion: { err in mtrExpectInvalidState(err) })
    cluster.stepColorTemperature(with: MTRColorControlClusterStepColorTemperatureParams(), expectedValues: [], expectedValueInterval: n(1), completionHandler: { err in mtrExpectInvalidState(err) })
    cluster.stepColor(with: MTRColorControlClusterStepColorParams(), expectedValues: [], expectedValueInterval: n(1), completion: { err in mtrExpectInvalidState(err) })
